package com.yuegang.zhihui.knowledge.api;
import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.knowledge.application.KnowledgeProcessingJobService;import com.yuegang.zhihui.knowledge.security.KnowledgeUserResolver;import jakarta.servlet.http.HttpServletRequest;import java.util.List;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/admin/knowledge/processing-jobs")public final class KnowledgeProcessingJobController{private final KnowledgeProcessingJobService service;private final KnowledgeUserResolver users;public KnowledgeProcessingJobController(KnowledgeProcessingJobService service,KnowledgeUserResolver users){this.service=service;this.users=users;}@GetMapping ApiResponse<List<KnowledgeProcessingJobView>>list(@RequestParam(required=false)String documentId,@RequestParam(required=false)String status,@RequestParam(defaultValue="50")int limit,HttpServletRequest request){users.resolve(request,true);return ApiResponse.success(service.list(documentId,status,limit),TraceIdResolver.resolve(request));}@PostMapping("/{id}/retry")ApiResponse<KnowledgeProcessingJobView>retry(@PathVariable String id,HttpServletRequest request){users.resolve(request,true);return ApiResponse.success(service.retry(id),TraceIdResolver.resolve(request));}}
